CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', preferred_locations text NOT NULL DEFAULT '', experience text NOT NULL DEFAULT '', qualifications text NOT NULL DEFAULT '', skills text NOT NULL DEFAULT '', job_categories text NOT NULL DEFAULT '', availability text NOT NULL DEFAULT '', training_interests text NOT NULL DEFAULT '', accommodation text NOT NULL DEFAULT '', serving_personnel boolean NOT NULL DEFAULT false, permissions_confirmed boolean NOT NULL DEFAULT false, consent_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT profile_lengths CHECK (length(full_name)<=100 AND length(phone)<=20 AND length(location)<=200 AND length(experience)<=2000 AND length(qualifications)<=2000 AND length(skills)<=2000 AND length(preferred_locations)<=500 AND length(job_categories)<=500 AND length(availability)<=500 AND length(training_interests)<=1000 AND length(accommodation)<=1000));
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_own_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK (id=auth.uid());
CREATE POLICY profiles_own_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_candidate_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id) ON CONFLICT DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER create_candidate_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_candidate_profile();
INSERT INTO public.profiles(id) SELECT id FROM auth.users ON CONFLICT DO NOTHING;
CREATE TABLE public.vacancies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, employer text NOT NULL, location text NOT NULL, job_type text NOT NULL DEFAULT 'Full time', responsibilities text NOT NULL DEFAULT '', eligibility text NOT NULL DEFAULT '', qualifications text NOT NULL DEFAULT '', salary text NOT NULL DEFAULT '', hours text NOT NULL DEFAULT '', benefits text NOT NULL DEFAULT '', deadline timestamptz, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','closed')), verified boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(length(title) BETWEEN 2 AND 150 AND length(employer) BETWEEN 2 AND 150 AND length(location) BETWEEN 2 AND 200 AND length(responsibilities)<=5000 AND length(eligibility)<=3000 AND length(qualifications)<=3000 AND length(salary)<=200 AND length(hours)<=500 AND length(benefits)<=2000));
GRANT SELECT ON public.vacancies TO anon,authenticated; GRANT INSERT,UPDATE ON public.vacancies TO authenticated; GRANT ALL ON public.vacancies TO service_role;
ALTER TABLE public.vacancies ENABLE ROW LEVEL SECURITY;
CREATE POLICY verified_open_vacancies ON public.vacancies FOR SELECT TO anon,authenticated USING(status='active' AND verified AND (deadline IS NULL OR deadline>now()));
CREATE POLICY admin_vacancy_read ON public.vacancies FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_vacancy_insert ON public.vacancies FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_vacancy_update ON public.vacancies FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, vacancy_id uuid NOT NULL REFERENCES public.vacancies(id), status text NOT NULL DEFAULT 'Submitted' CHECK(status IN ('Submitted','Reviewing','Interview','Offer','Placed','Not selected','Withdrawn')), candidate_note text NOT NULL DEFAULT '' CHECK(length(candidate_note)<=2000), interview_at timestamptz, staff_notes text NOT NULL DEFAULT '' CHECK(length(staff_notes)<=3000), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,vacancy_id));
GRANT SELECT,INSERT,UPDATE ON public.applications TO authenticated; GRANT ALL ON public.applications TO service_role;
ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY applications_own_read ON public.applications FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY applications_own_insert ON public.applications FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='Submitted' AND staff_notes='' AND interview_at IS NULL AND EXISTS(SELECT 1 FROM public.vacancies v WHERE v.id=vacancy_id AND v.status='active' AND v.verified AND (v.deadline IS NULL OR v.deadline>now())) AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.consent_at IS NOT NULL AND length(p.full_name)>=2 AND (NOT p.serving_personnel OR p.permissions_confirmed)));
CREATE POLICY application_admin_update ON public.applications FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.application_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.applications(id), status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.application_history TO authenticated; GRANT ALL ON public.application_history TO service_role;
ALTER TABLE public.application_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY application_history_read ON public.application_history FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.applications a WHERE a.id=application_id AND (a.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE FUNCTION public.audit_application() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status THEN INSERT INTO public.application_history(application_id,status) VALUES(NEW.id,NEW.status); END IF; RETURN NEW; END; $$;
CREATE TRIGGER audit_application AFTER INSERT OR UPDATE ON public.applications FOR EACH ROW EXECUTE FUNCTION public.audit_application();
CREATE TABLE public.site_content (key text PRIMARY KEY, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_content TO anon,authenticated; GRANT INSERT,UPDATE ON public.site_content TO authenticated; GRANT ALL ON public.site_content TO service_role;
ALTER TABLE public.site_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_content_read ON public.site_content FOR SELECT TO anon,authenticated USING(key IN ('carousel'));
CREATE POLICY admin_content_read ON public.site_content FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_content_insert ON public.site_content FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_content_update ON public.site_content FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.content_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), content_key text NOT NULL, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.content_history TO authenticated; GRANT ALL ON public.content_history TO service_role;
ALTER TABLE public.content_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY content_history_admin ON public.content_history FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.audit_site_content() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.content_history(content_key,actor_id) VALUES(NEW.key,auth.uid()); RETURN NEW; END; $$;
CREATE TRIGGER audit_site_content AFTER INSERT OR UPDATE ON public.site_content FOR EACH ROW EXECUTE FUNCTION public.audit_site_content();